<script setup lang="ts">import type{User}from'@career-launch/shared';import{onMounted,ref}from'vue';import PermissionGate from'../../components/PermissionGate.vue';import{repository}from'../../services/repository';const currentRole='super_admin' as const;const items=ref<User[]>([]);onMounted(async()=>{items.value=await repository.admin.operators.list()})</script>
<template><section><header class="admin-page-head"><div><h1>运营账号</h1><p>管理超级管理员与内容运营的后台访问权限。</p></div><PermissionGate :allow="['super_admin']" :current-role="currentRole"><button class="cl-primary-button">创建运营账号</button></PermissionGate></header><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>账号</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{item.nickname}}</strong><br/><span class="admin-muted">{{item.email}}</span></td><td>{{item.role==='super_admin'?'超级管理员':'内容运营'}}</td><td>{{item.status==='active'?'正常':'停用'}}</td><td><button class="admin-link-button">编辑</button><button class="admin-link-button">停用</button></td></tr></tbody></table></div></section></template>
